#include <iostream>
#include <cmath>

bool convertir_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const int candidato = static_cast<int>(origen);
    const double vuelta = static_cast<double>(candidato);
    if (vuelta != origen) {
        return false;
    }
    destino = candidato;
    return true;
}

int main() {
    double origen{-9.0};
    int destino{42};
    const bool integral = convertir_entero(origen, destino);
    std::cout << "Integral: " << integral << ";Destino: " << destino
              << ";Origen: " << origen << "\n";
    origen = 3.75;
    const bool positiva = convertir_entero(origen, destino);
    std::cout << "Fraccion positiva: " << positiva << ";Destino: " << destino
              << ";Origen: " << origen << "\n";
    origen = -1.5;
    const bool negativa = convertir_entero(origen, destino);
    std::cout << "Fraccion negativa: " << negativa << ";Destino: " << destino
              << ";Origen: " << origen << "\n";
    origen = -100.0;
    const bool frontera = convertir_entero(origen, destino);
    std::cout << "Frontera: " << frontera << ";Destino: " << destino
              << ";Origen: " << origen << "\n";
    origen = -100.5;
    const bool fuera = convertir_entero(origen, destino);
    std::cout << "Fuera: " << fuera << ";Destino: " << destino
